+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears in its first or last name (ignoring case and accents), and when its
+ * status is one of {@code statuses}, or {@code statuses} is empty.
+ *
+ * @param name     free text; blank matches every customer
+ * @param statuses accepted statuses; empty accepts every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip().replaceAll("\\s+", " ");
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized search terms of the name filter. */
+    public List<String> terms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(name.split(" ")).map(CustomerFilter::normalize).toList();
+    }
+
+    /** Lower-cases and strips diacritics, so matching ignores case and accents. */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD).replaceAll("\\p{M}+", "");
+        return Normalizer.normalize(decomposed, Normalizer.Form.NFC).toLowerCase(Locale.ROOT);
+    }
+}
